#include "protocol.h"
int cl_parse_request(const unsigned char*b,size_t n,uint32_t previous,struct cl_request*out){uint32_t id;if(!b||!out||n<8||n>CL_MAX_REQUEST||b[0]!=1||b[1]<1||b[1]>7||b[2]||b[3])return 0;id=(uint32_t)b[4]|((uint32_t)b[5]<<8)|((uint32_t)b[6]<<16)|((uint32_t)b[7]<<24);if(!id||id<=previous)return 0;out->opcode=b[1];out->id=id;out->body=b+8;out->bytes=n-8;return 1;}
struct scan{const unsigned char*b;size_t n,at;};
static void whitespace(struct scan*s){while(s->at<s->n&&(s->b[s->at]==' '||s->b[s->at]=='\t'||s->b[s->at]=='\r'||s->b[s->at]=='\n'))s->at++;}
static int literal(struct scan*s,const char*t){size_t i=0;while(t[i]){if(s->at+i>=s->n||s->b[s->at+i]!=(unsigned char)t[i])return 0;i++;}s->at+=i;return 1;}
static int string(struct scan*s,size_t*begin,size_t*end){unsigned c,j;if(s->at>=s->n||s->b[s->at++]!='"')return 0;*begin=s->at;while(s->at<s->n){c=s->b[s->at++];if(c=='"'){*end=s->at-1;return 1;}if(c<32)return 0;if(c=='\\'){if(s->at>=s->n)return 0;c=s->b[s->at++];if(c=='u'){for(j=0;j<4;j++){if(s->at>=s->n)return 0;c=s->b[s->at++];if(!((c>='0'&&c<='9')||(c>='a'&&c<='f')||(c>='A'&&c<='F')))return 0;}}else if(c!='"'&&c!='\\'&&c!='/'&&c!='b'&&c!='f'&&c!='n'&&c!='r'&&c!='t')return 0;}}return 0;}
static int span(const struct scan*s,size_t b,size_t e,const char*t){size_t i=0;while(t[i]){if(b+i>=e||s->b[b+i]!=(unsigned char)t[i])return 0;i++;}return b+i==e;}
int cl_catalog_json(unsigned op,const unsigned char*b,size_t n,int ro){struct scan s;unsigned mask=0,field;size_t begin,end,action_begin=0,action_end=0;if((op!=1&&op!=2&&op!=7)||!b||!n||n>16384||(ro&&op==1))return 0;s.b=b;s.n=n;s.at=0;whitespace(&s);if(!literal(&s,"{"))return 0;for(;;){whitespace(&s);if(!string(&s,&begin,&end))return 0;field=span(&s,begin,end,"action")?1:span(&s,begin,end,"path")?2:span(&s,begin,end,"principal")?4:span(&s,begin,end,"scope")?8:span(&s,begin,end,"bytes")?16:span(&s,begin,end,"directory")?32:0;if(!field||(mask&field))return 0;mask|=field;whitespace(&s);if(!literal(&s,":"))return 0;whitespace(&s);if(field==32){if(!literal(&s,"true")&&!literal(&s,"false"))return 0;}else{if(!string(&s,&begin,&end))return 0;if(field==1){action_begin=begin;action_end=end;}}whitespace(&s);if(literal(&s,"}"))break;if(!literal(&s,","))return 0;}whitespace(&s);if(s.at!=n)return 0;if(op==7)return mask==1&&span(&s,action_begin,action_end,"observe");if(op==1)return mask==34;if(span(&s,action_begin,action_end,"identity"))return mask==1;if(span(&s,action_begin,action_end,"inspect"))return mask==47;if(ro)return 0;if(span(&s,action_begin,action_end,"initialize"))return mask==1;if(span(&s,action_begin,action_end,"mkdir"))return mask==15;if(span(&s,action_begin,action_end,"write"))return mask==31;return 0;}
